/*
 * Release export map.
 *
 * Only the loader entry point is exported. All detector and collector entry
 * points reach Java through RegisterNatives, so nothing else needs to appear
 * in .dynsym. This removes the symbol names an analyst would otherwise use to
 * locate each check directly.
 */
{
    global:
        JNI_OnLoad;
    local:
        *;
};
